export function applyNormalizationIntegrityGate(decision:GuardrailDecision,normalization:ReportDesignNormalization,integrityIssues:MeasureIntegrityIssue[]):GuardrailDecision{const reasons=[...normalization.normalizationFindings.map(item=>item.reason),...integrityIssues.map(item=>item.reason)];if(!reasons.length)return decision;const evaluation={ruleId:'NORMALIZATION-001',category:'ai-output-validity' as const,result:'HUMAN_REVIEW_REQUIRED' as const,reason:`The normalized Report Design is not compiler-safe: ${reasons.join(' ')}`,recommendedAction:normalization.normalizationFindings[0]?.recommendedAction??integrityIssues[0]?.recommendedAction??'Correct the Report Design before generation.',severity:'error' as const};const outcome=['BLOCKED','OUT_OF_SCOPE'].includes(decision.outcome)?decision.outcome:'HUMAN_REVIEW_REQUIRED';return{outcome,generation:'NOT_STARTED',evaluations:[...decision.evaluations,evaluation]}}
