type ReportDesignPipelineServices={normalize?:typeof normalizeReportDesign;normalizeMeasures?:typeof normalizeMeasureContracts;validate?:(design:ReportDesign,citations:readonly string[],schema:DataStructure)=>ReportDesign;guardrails?:typeof evaluateGuardrails;compile?:typeof compileWithTrace};
export function executeReportDesignPipeline(originalReportDesign:ReportDesign,data:DataStructure,citations:readonly string[],interpretation:RequirementInterpretation,tenant:TenantSettings,onTrace:(update:Partial<Trace>)=>void=()=>{},services:ReportDesignPipelineServices={},confirmedRequirements?:unknown){
  if(originalReportDesign.schema_version===2){
    assertAuthoredGeometry(originalReportDesign);const validate=services.validate??validateReportDesign,guardrails=services.guardrails??evaluateGuardrails,compile=services.compile??compileWithTrace;
    validate(originalReportDesign,citations,data);const normalization=normalizeReportDesign(originalReportDesign,data),decision=guardrails(interpretation,originalReportDesign,data,tenant);
    onTrace({normalization,measureNormalizationActions:[],guardrails:decision.evaluations,finalStatus:decision.generation==='NOT_STARTED'?decision.outcome:'Technical generation checks passed'});
    const compilation=decision.generation==='AVAILABLE'&&tenant.generation.enabled?compile(originalReportDesign,data,tenant,onTrace):null;
    return{originalReportDesign,normalizedReportDesign:originalReportDesign,normalization,measureNormalizationActions:[],integrityIssues:[],coverageInspection:null,decision,compilation};
  }
  const normalize=services.normalize??normalizeReportDesign,normalizeMeasures=services.normalizeMeasures??normalizeMeasureContracts,validate=services.validate??validateReportDesign,guardrails=services.guardrails??evaluateGuardrails,compile=services.compile??compileWithTrace;
  const normalization=normalize(originalReportDesign,data),measureNormalization=normalizeMeasures(normalization.normalizedReportDesign),normalizedReportDesign=measureNormalization.normalizedReportDesign;normalization.normalizedReportDesign=normalizedReportDesign;let integrityIssues:MeasureIntegrityIssue[]=[];
  try{validate(normalizedReportDesign,citations,data)}catch(reason){if(!(reason instanceof ReportDesignIntegrityError))throw reason;integrityIssues=reason.issues}
  const coverageInspection=confirmedRequirements===undefined?null:inspectLayoutRepairSemantics(normalizedReportDesign,normalizedReportDesign,confirmedRequirements),decision=applyConfirmedCoverageGate(applyNormalizationIntegrityGate(guardrails(interpretation,normalizedReportDesign,data,tenant),normalization,integrityIssues),coverageInspection);onTrace({normalization,measureNormalizationActions:measureNormalization.actions,guardrails:decision.evaluations,finalStatus:decision.generation==='NOT_STARTED'?decision.outcome:'Generation checks passed'});
  const compilation=decision.generation==='AVAILABLE'&&tenant.generation.enabled?compile(normalizedReportDesign,data,tenant,onTrace):null;
  return{originalReportDesign,normalizedReportDesign,normalization,measureNormalizationActions:measureNormalization.actions,integrityIssues,coverageInspection,decision,compilation};
}
type LayoutRepairContext={confirmedRequirements:unknown;chunks:Array<{citation:string;text:string}>};
type LayoutRepairService=(snapshot:unknown,schema:unknown,tenant:TenantSettings,chunks:Array<{citation:string;text:string}>,originalReportDesign:ReportDesign,geometryEvidence:unknown)=>Promise<AIResult<ReportDesign>>;
export async function executeReportDesignPipelineWithLayoutRepair(originalReportDesign:ReportDesign,data:DataStructure,citations:readonly string[],interpretation:RequirementInterpretation,tenant:TenantSettings,repairContext:LayoutRepairContext,onTrace:(update:Partial<Trace>)=>void=()=>{},services:ReportDesignPipelineServices&{repair?:LayoutRepairService}={}){
  assertAuthoredGeometry(originalReportDesign);
 const immutableOriginal=structuredClone(originalReportDesign),first=executeReportDesignPipeline(immutableOriginal,data,citations,interpretation,tenant,onTrace,services,repairContext.confirmedRequirements);
  const independentStop=first.decision.evaluations.some(item=>item.ruleId!=='NORMALIZATION-001'&&!['PASS','WARNING'].includes(item.result));
  if(!isLayoutRepairEligible(first.normalization)||first.integrityIssues.length||independentStop)return{...first,originalReportDesign:immutableOriginal,initialNormalization:first.normalization,layoutRepair:null,repairedReportDesign:null,compilerStatus:first.compilation?.compiler};
  const repair=services.repair??repairGroundedReportDesignLayout,initialNormalization=structuredClone(first.normalization),evidence:LayoutRepairEvidence={attempted:true,result:'FAILED',originalReportDesign:structuredClone(immutableOriginal),initialNormalization};let repairCompilerStatus:string|undefined;
  try{
    const repaired=await repair(repairContext.confirmedRequirements,data,tenant,repairContext.chunks,structuredClone(immutableOriginal),{normalizationFindings:initialNormalization.normalizationFindings,pageLayouts:initialNormalization.pageLayouts}),repairedReportDesign=structuredClone(repaired.value);
    evidence.repairedReportDesign=repairedReportDesign;evidence.metrics=repaired.metrics;evidence.semanticInspection=inspectLayoutRepairSemantics(immutableOriginal,repairedReportDesign,repairContext.confirmedRequirements);evidence.semanticFindings=evidence.semanticInspection.findings;if(evidence.semanticInspection.status==='FAIL'){evidence.result='UNRESOLVED';evidence.reason='Deterministic confirmed-requirement coverage could not be proven.';onTrace({layoutRepair:evidence,finalStatus:'HUMAN_REVIEW_REQUIRED'});return{...first,originalReportDesign:immutableOriginal,initialNormalization,layoutRepair:evidence,repairedReportDesign,compilerStatus:first.compilation?.compiler}}
    onTrace({layoutRepair:{...evidence,result:'UNRESOLVED'},finalStatus:'Layout repair received; deterministic checks running'});
    const second=executeReportDesignPipeline(repairedReportDesign,data,citations,interpretation,tenant,update=>{if(update.compiler)repairCompilerStatus=update.compiler;onTrace(update)},services,repairContext.confirmedRequirements),succeeded=second.decision.generation==='AVAILABLE'&&Boolean(second.compilation?.validation.status==='PASS');
    const layoutRepair={...evidence,result:succeeded?'SUCCEEDED':'UNRESOLVED'} as LayoutRepairEvidence;onTrace({layoutRepair,finalStatus:succeeded?'Layout repair validated':second.decision.outcome});
    return{...second,originalReportDesign:immutableOriginal,initialNormalization,layoutRepair,repairedReportDesign,compilerStatus:second.compilation?.compiler??repairCompilerStatus};
  }catch(reason){evidence.reason=reason instanceof Error?reason.message:'Layout repair failed';onTrace({layoutRepair:evidence,...(repairCompilerStatus?{compiler:repairCompilerStatus}:{}),finalStatus:'HUMAN_REVIEW_REQUIRED'});return{...first,originalReportDesign:immutableOriginal,initialNormalization,layoutRepair:evidence,repairedReportDesign:evidence.repairedReportDesign??null,compilerStatus:repairCompilerStatus??first.compilation?.compiler}}
}
const nav:Array<{group:string;items:Array<[View,string,string]>}>=[{group:'Workspace',items:[['create','Create Report','＋'],['runs','My Runs','◷']]},{group:'Administration',items:[['tenant','Tenant Settings','⚙'],['ai','AI & Models','AI'],['knowledge','Governed Knowledge','▤'],['branding','Branding & Report Standards','◆'],['guardrails','Guardrails & Generation','✓']]}];
const outcomeLabel=(value:string)=>value.replaceAll('_',' ').replace(/\b\w/g,char=>char.toUpperCase());
export const deploymentGuideEligible=(candidate:GenericCandidate|null,design:ReportDesign|null,validation:CandidateValidation|null,decision:GuardrailDecision|null)=>Boolean(candidate&&design&&validation?.status==='PASS'&&decision?.generation==='AVAILABLE');
export type WorkflowPresentationState={requirementEntered:boolean;dataReady:boolean;interpretationKind?:RequirementInterpretation['request_kind'];requirementsConfirmed:boolean;designReady:boolean;decision?:GuardrailDecision|null;validationStatus?:CandidateValidation['status'];busy?:string};
export function workflowStages(state:WorkflowPresentationState):Array<{label:string;state:StageState}>{
  const labels=['Requirement','Data','Clarify','Design','Validate','Generate'];
  let states:StageState[];
  if(state.interpretationKind==='OUT_OF_SCOPE')states=['attention','waiting','waiting','waiting','waiting','waiting'];
  else if(state.decision?.generation==='NOT_STARTED')states=['completed','completed','completed','completed','attention','waiting'];
  else if(state.decision?.generation==='AVAILABLE'&&state.validationStatus==='FAIL')states=['completed','completed','completed','completed','attention','waiting'];
  else if(state.decision?.generation==='AVAILABLE'&&state.validationStatus==='PASS')states=['completed','completed','completed','completed','completed','completed'];
  else if(state.designReady)states=['completed','completed','completed','completed','current','waiting'];
  else if(state.requirementsConfirmed&&state.busy==='Applying organisational standards')states=['completed','completed','completed','current','waiting','waiting'];
  else if(state.interpretationKind==='POWER_BI_REPORT')states=['completed','completed',state.requirementsConfirmed?'completed':'current',state.requirementsConfirmed?'current':'waiting','waiting','waiting'];
  else if(state.requirementEntered&&!state.dataReady)states=['completed','current','waiting','waiting','waiting','waiting'];
  else if(state.dataReady)states=['current','completed','waiting','waiting','waiting','waiting'];
  else states=['current','waiting','waiting','waiting','waiting','waiting'];
  return labels.map((label,index)=>({label,state:states[index]}));
}

export function EnterprisePrototypeApp({caseRecord}:{caseRecord?:CaseRecord}={}){
  const [view,setView]=useState<View>('create');const [tenant,setTenant]=useState<TenantSettings>(structuredClone(defaultTenantSettings));const [service,setService]=useState<FoundryStatus|null|undefined>(undefined);const [knowledgeDocuments,setKnowledgeDocuments]=useState<KnowledgeDocument[]>(defaultDocuments);const [lastIndexed,setLastIndexed]=useState('Not indexed in this session');const [runs,setRuns]=useState<RunRecord[]>([]);
  useEffect(()=>{void foundryStatus().then(setService).catch(()=>setService(null))},[]);
  const serviceLabel=service===undefined?'Checking AI service…':service?.configured?'AI service connected':'AI service unavailable';const serviceTone=service===undefined?'neutral':service?.configured?'success':'danger';
  return <div className="app-shell"><aside className="side-nav"><div className="brand"><span className="brand-mark">A</span><div><strong>APBRA</strong><small>Power BI automation</small></div></div>{nav.map(section=><nav key={section.group} aria-label={section.group}><p>{section.group}</p>{section.items.map(([id,label,icon])=><NavItem key={id} active={view===id} label={label} icon={icon} onClick={()=>setView(id)}/>)}</nav>)}<p className="session-note">Runs are retained for this browser session.</p></aside><div className="app-main"><header className="top-bar"><div><strong>{tenant.organisation.displayName}</strong><span>{view==='create'?'Report generation':view==='runs'?'Run history':'Administration'}</span></div><StatusBadge tone={serviceTone}>{serviceLabel}</StatusBadge></header>{view==='create'&&<CreateReport tenant={tenant} documents={knowledgeDocuments} initialRequirement={caseRecord?.current_request.request_text} caseVersion={caseRecord?.version} onIndexed={()=>setLastIndexed(new Date().toLocaleString())} onRun={run=>setRuns(current=>[run,...current])}/>} {view==='runs'&&<MyRuns runs={runs}/>} {view==='tenant'&&<TenantSettingsPage value={tenant} onChange={setTenant}/>} {view==='ai'&&<AIModelsPage service={service} tenant={tenant}/>} {view==='knowledge'&&<KnowledgePage documents={knowledgeDocuments} lastIndexed={lastIndexed} onChange={setKnowledgeDocuments} onReindex={()=>{clearRagIndex();setLastIndexed('Index cleared; it will rebuild on the next report run.')}}/>} {view==='branding'&&<BrandingPage value={tenant} onChange={setTenant}/>} {view==='guardrails'&&<GuardrailsPage value={tenant} onChange={setTenant}/>}</div></div>
}

