const tenantSectionFields:Record<TenantSettingsSection,readonly string[]>={
  ai_models:['automatic_generation_enabled','clarification_enabled','expert_escalation_enabled','provider_profile'],
  responses_standards:['conventions','delivery_guide_policy','generation_policy.generation','generation_policy.governance'],
  budgets_limits:['invitation_ttl_days','upload_policy','clarification_policy','max_clarification_rounds_per_cycle','max_clarification_rounds_overall'],
  branding_organisation:['generation_policy.branding','generation_policy.organisation'],
};
const tenantSections=Object.keys(tenantSectionFields) as TenantSettingsSection[];
function settingAtPath(settings:TenantSettingsDocument,path:string):unknown{return path.split('.').reduce<unknown>((part,key)=>(part as Record<string,unknown>)[key],settings)}
export function settingsSectionChanges(before:TenantSettingsDocument,after:TenantSettingsDocument,section:TenantSettingsSection):Record<string,unknown>{return Object.fromEntries(tenantSectionFields[section].filter(path=>JSON.stringify(settingAtPath(before,path))!==JSON.stringify(settingAtPath(after,path))).map(path=>[path,structuredClone(settingAtPath(after,path))]))}
function applySectionChanges(settings:TenantSettingsDocument,changes:Record<string,unknown>):TenantSettingsDocument{const next=structuredClone(settings),root=next as unknown as Record<string,unknown>;for(const [path,value] of Object.entries(changes)){const parts=path.split('.'),target=parts.slice(0,-1).reduce<Record<string,unknown>>((part,key)=>part[key] as Record<string,unknown>,root);target[parts[parts.length-1]]=structuredClone(value)}return next}
function preserveSettingsDraft(before:TenantSettingsDocument,draft:TenantSettingsDocument,latest:TenantSettingsDocument):TenantSettingsDocument{const changedKeys=settingsChangedKeys(before,draft);return applySectionChanges(latest,Object.fromEntries(changedKeys.map(key=>[key,structuredClone(settingAtPath(draft,key))])))}

function settingsChangedKeys(before:TenantSettingsDocument,after:TenantSettingsDocument):string[]{
  const visit=(left:unknown,right:unknown,path:string):string[]=>{
    if(JSON.stringify(left)===JSON.stringify(right))return [];
    if(path==='provider_profile'&&left&&right){
      const before=left as TenantProviderProfile,afterProfile=right as TenantProviderProfile;
      if(!matchesQualificationIdentity(before,afterProfile))return [path];
      return (['max_calls_per_operation','max_input_characters','max_output_tokens','time_budget_seconds','request_timeout_seconds','retry_limit'] as const).filter(key=>before[key]!==afterProfile[key]).map(key=>`${path}.${key}`);
    }
    if(path==='conventions.terminology'||left===null||right===null||typeof left!=='object'||typeof right!=='object'||Array.isArray(left)||Array.isArray(right))return [path];
    return Object.keys(right as Record<string,unknown>).flatMap(key=>visit((left as Record<string,unknown>)[key],(right as Record<string,unknown>)[key],path?`${path}.${key}`:key));
  };
  return visit(before,after,'');
}

function settingConsequence(key:string):string{
  if(key==='provider_profile')return 'May change the qualified model or deployment and require a new protected credential.';
  if(key.startsWith('provider_profile.'))return 'Changes the permitted model call, retry, size or time budget for future operations.';
  if(key==='automatic_generation_enabled')return 'Changes whether new automatic designs are available; enabling requires a qualified profile and credential.';
  if(key.startsWith('generation_policy'))return 'May change future report capability, validation, budgets, branding or generated meaning; accepted work may need revalidation.';
  if(key.startsWith('conventions'))return 'May change naming or modelling standards for new or revalidated reports.';
  if(key.includes('clarification'))return 'May change future clarification availability or limits, not historical answers.';
  if(key==='expert_escalation_enabled')return 'Changes availability of the explicit expert-assistance route.';
  return 'Applies to future operations; existing immutable history is unchanged.';
}

export function configuredAgentName(profile:Pick<TenantProviderProfile,'protocol'|'endpoint'>|null|undefined):string|null{
  if(profile?.protocol!=='FOUNDRY_AGENT_RESPONSES')return null;
  try{const endpoint=new URL(profile.endpoint),match=endpoint.pathname.match(/\/agents\/([^/]+)\/endpoint\/protocols\/openai\/responses$/);return endpoint.protocol==='https:'&&match?decodeURIComponent(match[1]):null}catch{return null}
}

export function providerAuthenticationLabel(protocol:TenantProviderProfile['protocol']|undefined):string{
  return protocol==='FOUNDRY_AGENT_RESPONSES'?'Foundry agent · Microsoft Entra server identity':'Protected provider credential';
}

export function settingDisplayValue(value:unknown):string{return value===undefined?'Unavailable':typeof value==='string'?value:JSON.stringify(value,null,2)}
export function settingLabel(key:string):string{const labels:Record<string,string>={provider_profile:'Approved AI profile',automatic_generation_enabled:'Automatic intelligent generation',clarification_enabled:'Model-led clarification',expert_escalation_enabled:'Expert assistance'};return labels[key]??key.replaceAll('_',' ').replaceAll('.',' · ').replace(/([a-z])([A-Z])/g,'$1 $2')}

function matchesQualificationIdentity(selected:TenantProviderProfile,qualified:TenantProviderProfile):boolean{
  return selected.profile_id===qualified.profile_id&&selected.protocol===qualified.protocol&&selected.endpoint===qualified.endpoint&&selected.model_or_deployment===qualified.model_or_deployment&&selected.api_version===qualified.api_version&&(selected.agent_version??null)===(qualified.agent_version??null)&&selected.region===qualified.region&&selected.prompt_version===qualified.prompt_version&&selected.configuration_id===qualified.configuration_id&&JSON.stringify(selected.capabilities)===JSON.stringify(qualified.capabilities);
}

function TenantSettingsDialog({label,busy,onClose,children}:{label:string;busy:boolean;onClose:()=>void;children:React.ReactNode}){
  const dialog=useRef<HTMLDialogElement>(null),title=useId();
  useEffect(()=>{
    const element=dialog.current!;
    const opener=document.activeElement;
    element.showModal();
    element.querySelector<HTMLButtonElement>('button')?.focus();
    return()=>{element.close();if(opener instanceof HTMLElement&&opener.isConnected)opener.focus()};
  },[]);
  useEffect(()=>{if(busy)dialog.current?.focus()},[busy]);
  return <dialog ref={dialog} tabIndex={-1} aria-busy={busy} aria-label={label} aria-labelledby={title} className="tenant-dialog tenant-settings-dialog" onCancel={event=>{event.preventDefault();if(!busy)onClose()}} onKeyDown={containDialogFocus}><header className="tenant-modal-header"><h2 id={title}>{label}</h2><button type="button" className="subtle" disabled={busy} onClick={onClose}>Close</button></header><div className="tenant-modal-body">{children}</div></dialog>;
}

export function SettingsHistoryPanel({items,scope,busy=false,reconciliationRequired=false,error=false,onRefresh,onRestore}:{items:TenantSettingsHistory[];scope:string;busy?:boolean;reconciliationRequired?:boolean;error?:boolean;onRefresh:()=>void;onRestore:(item:TenantSettingsHistory)=>void}){
  const historyPage=usePagedItems(items,scope);
  return <details className="admin-settings-history"><summary>Settings history <span className="status-badge status-neutral">{error?'Unavailable':`${items.length} versions`}</span></summary><section aria-labelledby="settings-history-heading"><div className="section-title"><div><h3 id="settings-history-heading">Settings history</h3><p>Restore creates a new version. Historical versions are retained unchanged.</p></div><button type="button" className="subtle" disabled={busy} onClick={()=>onRefresh()}>Refresh settings history</button></div>
      {error&&<AdminState kind="error" title="Settings history could not be loaded" action={<button type="button" className="subtle" onClick={()=>onRefresh()}>Retry settings history</button>}><p>The current effective settings remain available.</p></AdminState>}
      {!error&&items.length===0&&<AdminState kind="empty" title="No settings history returned"><p>No versions are available in this view.</p></AdminState>}
      {!error&&items.length>0&&<AdminTableRegion label="Settings version history"><table className="admin-data-table settings-history-table"><caption className="sr-only">Retained tenant settings versions</caption><thead><tr><th scope="col">Version</th><th scope="col">Recorded (display time zone)</th><th scope="col">Changes</th><th scope="col">Status</th><th scope="col"><span className="sr-only">Version actions</span></th></tr></thead><tbody>{historyPage.items.map(item=><tr key={item.id}><th scope="row">Version {item.version}</th><td><TenantTime value={item.created_at}/></td><td>{item.changed_keys.length?item.changed_keys.map(settingLabel).join(', '):'Initial configuration'}</td><td><span className={`status-badge ${item.current?'status-info':'status-neutral'}`}>{item.current?'Current':'Previous'}</span></td><td>{!item.current&&<button type="button" className="subtle" disabled={busy||reconciliationRequired} onClick={()=>onRestore(item)}>Review restore<span className="sr-only"> of version {item.version}</span></button>}</td></tr>)}</tbody></table></AdminTableRegion>}
      {!error&&<Pagination label="Settings history" total={historyPage.total} page={historyPage.page} pageSize={historyPage.pageSize} onPage={historyPage.onPage} onPageSize={historyPage.onPageSize} disabled={busy||reconciliationRequired}/>}
    </section></details>;
}

