  type Intent={key:string;kind:KnowledgeCommand['kind'];id:string|null;body:string;membership:string;company:string;csrf:string;epoch:number};
  const contextKey=`${session.actor?.company_id}/${session.actor?.membership_id}/${session.actor?.identity_id}/${session.csrf_token}`,previousContext=useRef(contextKey);
  const pending=useRef<Intent|null>(null),writeToken=useRef(session.csrf_token),running=useRef(false),epoch=useRef(0),mounted=useRef(false),listRead=useRef(0);
  const actor=session.actor!,dirty=JSON.stringify(draft)!==JSON.stringify(baseline);
  const documentPage=usePagedItems(items,contextKey),revisionPage=usePagedItems(history?.revisions??[],`${contextKey}:${selected?.document_id??''}`);
  useLayoutEffect(()=>{onAbandonmentChanged(dirty||pending.current!==null);return()=>onAbandonmentChanged(false)},[dirty,uncertain,busy,contextKey,onAbandonmentChanged]);
  const valid=(at:number)=>mounted.current&&epoch.current===at;
  const sameCompany=(value:{company_id:string},company=actor.company_id)=>{if(!value||typeof value.company_id!=='string')throw new ApiError(503,'KNOWLEDGE_DOCUMENTS_UNAVAILABLE','Document response unavailable.');if(value.company_id!==company)throw new ApiError(409,'KNOWLEDGE_CONTEXT_CHANGED','Document context changed.');};
  const clearSensitive=()=>{onAbandonmentChanged(false);epoch.current++;listRead.current++;pending.current=null;writeToken.current=undefined;setCapabilities(null);setItems([]);setListLoaded(false);setListFailed(false);setSelected(null);setHistory(null);setOriginal(null);setDraft({title:'',source_version:'',text:''});setBaseline({title:'',source_version:'',text:''});setUncertain(false);setRetrySame(false);setConflict(false);setArchiveOpen(false);setBlocked(true);setEditorReady(false);setMessage('Document access changed. Refresh the current authorized context before continuing.');};
