  useEffect(()=>{if(!dirty&&!uncertain&&!busy)return;const warn=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue=''};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn)},[dirty,uncertain,busy]);
  async function refreshList(member:string,at:number){const read=++listRead.current;setListFailed(false);try{const value=await knowledgeDocumentsApi.list(member);if(!valid(at)||read!==listRead.current)return;sameCompany(value);for(const item of value.items)sameCompany(item);setItems(value.items);setListLoaded(true)}catch(error){if(valid(at)&&read===listRead.current)setListFailed(true);throw error}}
