  async function loadHistory(){if(!selected||!capabilities||running.current)return;const at=epoch.current,id=selected.document_id;running.current=true;setBusy(true);try{const value=await knowledgeDocumentsApi.history(id,capabilities.membership_id);if(!valid(at))return;sameCompany(value);if(value.document.document_id!==id)throw new ApiError(409,'KNOWLEDGE_CONTEXT_CHANGED','Document context changed.');setHistory(value);if(value.document.current_revision_id!==selected.current_revision_id)setConflict(true);setSelected(value.document);setMessage('History loaded. Original revisions are retained.')}catch(error){if(valid(at))failure(error)}finally{running.current=false;if(mounted.current)setBusy(false)}}
