  async function committed(value:KnowledgeCommandEnvelope|KnowledgeReconciliation,intent:Intent){sameCompany(value,intent.company);if(!value.command||!value.document||value.command.command_key!==intent.key||value.command.kind!==intent.kind||value.document.document_id!==value.command.document_id||(intent.id!==null&&value.command.document_id!==intent.id))throw new ApiError(503,'KNOWLEDGE_DOCUMENTS_UNAVAILABLE','Document response unavailable.');sameCompany(value.document,intent.company);pending.current=null;setUncertain(false);setRetrySame(false);setArchiveOpen(false);setConflict(intent.kind!=='ARCHIVE'&&value.document.current_revision_id!==value.command.target_revision_id);setSelected(value.document);if(intent.kind!=='ARCHIVE'){const saved=JSON.parse(intent.body) as KnowledgeOriginalDraft;setBaseline({title:saved.title,source_version:saved.source_version,text:saved.text});}setMessage('Draft saved in this workspace. It has not been sent to your agent or used for answers. The current revision is shown separately from this save.');try{await refreshList(intent.membership,intent.epoch)}catch(error){if(valid(intent.epoch)){if(error instanceof ApiError&&(error.status===401||error.status===403||error.code==='KNOWLEDGE_CONTEXT_CHANGED'))failure(error);else setMessage('Saved locally, but the document list could not be refreshed. The committed operation remains saved.')}}}
  async function send(intent:Intent){running.current=true;setBusy(true);setRetrySame(false);try{const value=await knowledgeDocumentsApi.submit(intent.kind,intent.id,intent.body,intent.key,intent.membership,intent.csrf);if(valid(intent.epoch)&&pending.current===intent)await committed(value,intent)}catch(error){if(!valid(intent.epoch)||pending.current!==intent)return;if(error instanceof ApiError&&(error.status===401||error.status===403||error.code==='KNOWLEDGE_CONTEXT_CHANGED'))failure(error);else if(!(error instanceof ApiError)||error.status>=500){setUncertain(true);setArchiveOpen(false);setMessage('The save outcome is unknown. Your original command and text are kept. Check this command before any further document write.')}else{pending.current=null;setArchiveOpen(false);setConflict(error instanceof ApiError&&error.status===409);setMessage(error instanceof ApiError&&error.status===409?'The saved revision or command changed. Your draft is kept; load the latest document before making a new intent.':error instanceof ApiError&&error.status===413?'This request exceeds the current company request-size limit. Your draft is kept.':'The request was rejected. Your draft is kept.')}}finally{running.current=false;if(mounted.current)setBusy(false)}}
