  async function reconcile(){const intent=pending.current;if(!intent||running.current||!valid(intent.epoch))return;running.current=true;setBusy(true);try{const value=await knowledgeDocumentsApi.reconcile(intent.key,intent.membership);if(!valid(intent.epoch)||pending.current!==intent)return;sameCompany(value,intent.company);if(value.reconciliation==='COMMITTED')await committed(value,intent);else if(value.reconciliation==='NOT_OBSERVED'&&value.command===null&&value.document===null){setRetrySame(true);setMessage('This command was not observed at this read. This does not prove failure. Retry only the same original command and text.')}else throw new ApiError(409,'KNOWLEDGE_CONTEXT_CHANGED','Document context changed.')}catch(error){if(valid(intent.epoch))failure(error)}finally{running.current=false;if(mounted.current)setBusy(false)}}
