        {listFailed&&<AdminState kind="error" title="The document list could not be refreshed"><p>{listLoaded?'The last loaded list is retained below. Refresh before relying on its current state.':'No current list is available. Retry the list read before assuming it is empty.'}</p></AdminState>}
        {!listFailed&&listLoaded&&items.length===0&&<AdminState kind="empty" title="No local documents saved"><p>You can prepare a local text draft below. It will not be used by AI.</p></AdminState>}
        {!listFailed&&!listLoaded&&<AdminState kind="loading" title="Loading the document list"/>}
        {items.length>0&&<AdminTableRegion label="Local documents table"><table className="admin-data-table document-list-table"><caption className="sr-only">Local document drafts. Open a document to view its full text and retained history.</caption><thead><tr><th scope="col">Document</th><th scope="col">Local status</th><th scope="col"><span className="sr-only">Actions</span></th></tr></thead><tbody>{documentPage.items.map(item=><tr key={item.document_id}><th scope="row">{item.current_revision?item.current_revision.title||'(Empty title)':'Archived local document'}<span className="document-current">Source version: {item.current_revision?.source_version||'Not recorded'}</span>{selected?.document_id===item.document_id&&<span className="status-badge status-neutral">Selected</span>}</th><td>{item.local_state==='LOCAL_ARCHIVAL_REQUESTED'?'Archival requested':'Draft'}</td><td><button type="button" className="subtle" disabled={busy||uncertain} aria-label={`Open document ${item.current_revision?.title||item.document_id}`} onClick={()=>void openDocument(item)}>Open</button></td></tr>)}</tbody></table></AdminTableRegion>}
